import React from "react";
import {interpolate, spring, useCurrentFrame, useVideoConfig} from "remotion";
import {C, Reveal, Stage, useEnter} from "./lib/kit";

const W = 1680;

export default function Scene() {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const zone = useEnter(40);
  const pos = interpolate(spring({frame: frame - 30, fps, config: {damping: 20, stiffness: 50}}), [0, 1], [0, 0.65]);
  const ticks = [{v: 80, t: "80"}, {v: 90, t: "90"}, {v: 96, t: "96"}, {v: 100, t: "100"}];
  return (
    <Stage index="01" kicker="Trois gestes" title="L'eau">
      <Reveal delay={14}>
        <div style={{fontSize: 190, fontWeight: 700, color: C.accent, lineHeight: 1}}>90 à 96 °C</div>
      </Reveal>
      <Reveal delay={24}>
        <div style={{fontSize: 56, color: C.ink, marginTop: 14}}>Chaude, pas bouillante.</div>
      </Reveal>
      <div style={{position: "absolute", left: 0, top: 400, width: W, height: 140}}>
        <div style={{position: "absolute", top: 30, left: 0, width: W, height: 28, borderRadius: 14, background: C.dim}} />
        <div style={{position: "absolute", top: 30, left: W * 0.5, width: W * 0.3 * zone, height: 28, borderRadius: 14, background: C.accent}} />
        <div style={{position: "absolute", top: 10, left: W * pos - 4, width: 8, height: 68, borderRadius: 4, background: C.ink}} />
        {ticks.map((k) => (
          <div key={k.t} style={{position: "absolute", top: 96, left: W * ((k.v - 80) / 20) - 60, width: 120, textAlign: "center", fontSize: 34, color: C.mute}}>{k.t}°</div>
        ))}
        <div style={{position: "absolute", top: 96, left: W - 60, width: 300, fontSize: 28, color: C.mute, opacity: zone, display: "none"}} />
      </div>
      <Reveal delay={70} style={{position: "absolute", left: 0, top: 560, fontSize: 40, color: C.mute}}>
        100° : l'ébullition
      </Reveal>
    </Stage>
  );
}

