import React from "react";
import {interpolate, useCurrentFrame} from "remotion";
import {C, Reveal, Stage} from "./lib/kit";

const W = 1680;

export default function Scene() {
  const frame = useCurrentFrame();
  const p = interpolate(frame, [20, 95], [0, 1], {extrapolateLeft: "clamp", extrapolateRight: "clamp"});
  const focus = interpolate(frame, [100, 115], [0, 1], {extrapolateLeft: "clamp", extrapolateRight: "clamp"});
  const segs = [
    {name: "Acidité", when: "au début", mid: false},
    {name: "Douceur", when: "ensuite", mid: true},
    {name: "Amertume", when: "à la fin", mid: false}
  ];
  const segW = W / 3;
  return (
    <Stage index="03" kicker="Trois gestes" title="L'extraction">
      <Reveal delay={12}>
        <div style={{fontSize: 52, color: C.mute}}>Le café se délivre dans cet ordre.</div>
      </Reveal>
      <div style={{position: "absolute", left: 0, top: 130, width: W}}>
        <div style={{display: "flex"}}>
          {segs.map((s, i) => {
            const fill = Math.max(0, Math.min(1, p * 3 - i));
            const dimmed = s.mid ? 1 : 1 - 0.6 * focus;
            return (
              <div key={s.name} style={{width: segW, padding: "0 8px", boxSizing: "border-box", opacity: dimmed}}>
                <div style={{height: 64, borderRadius: 14, background: C.dim, overflow: "hidden"}}>
                  <div style={{height: 64, width: `${fill * 100}%`, background: s.mid ? C.accent : C.mute}} />
                </div>
                <div style={{fontSize: 58, fontWeight: 700, marginTop: 22, color: s.mid && focus > 0.5 ? C.accent : C.ink}}>{s.name}</div>
                <div style={{fontSize: 40, color: C.mute, marginTop: 4}}>{s.when}</div>
              </div>
            );
          })}
        </div>
      </div>
      <Reveal delay={105} style={{position: "absolute", left: 0, top: 440, fontSize: 64, fontWeight: 700}}>
        Ni trop tôt, ni trop tard.
      </Reveal>
    </Stage>
  );
}

