import {C, Reveal, Stage} from "./lib/kit";

const Dots: React.FC<{r: number; cols: number; rows: number; color: string}> = ({r, cols, rows, color}) => {
  const gap = 2 * r * 1.7;
  const w = cols * gap;
  const h = rows * gap;
  const dots = [];
  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {
      const jx = Math.sin(i * 12.9 + j * 78.2) * r * 0.5;
      const jy = Math.cos(i * 39.3 + j * 11.1) * r * 0.5;
      dots.push(<circle key={`${i}-${j}`} cx={gap / 2 + i * gap + jx} cy={gap / 2 + j * gap + jy} r={r * (0.8 + 0.2 * Math.abs(Math.sin(i * 3 + j * 7)))} fill={color} />);
    }
  }
  return <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`}>{dots}</svg>;
};

export default function Scene() {
  const frame = useCurrentFrame();
  const hl = interpolate(frame, [60, 80], [0, 1], {extrapolateLeft: "clamp", extrapolateRight: "clamp"});
  const cards = [
    {label: "Trop fine", note: "amer", r: 4, cols: 24, rows: 9, delay: 14, mid: false},
    {label: "Moyenne", note: "équilibré", r: 9, cols: 11, rows: 5, delay: 24, mid: true},
    {label: "Trop grosse", note: "acide", r: 18, cols: 5, rows: 3, delay: 34, mid: false}
  ];
  return (
    <Stage index="02" kicker="Trois gestes" title="La mouture">
      <div style={{display: "flex", gap: 48}}>
        {cards.map((c) => {
          const op = c.mid ? 1 : 1 - 0.65 * hl;
          return (
            <Reveal key={c.label} delay={c.delay} style={{flex: 1}}>
              <div style={{height: 470, borderRadius: 28, border: `3px solid ${c.mid && hl > 0.5 ? C.accent : C.dim}`, background: "#171310", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "space-between", padding: "36px 20px", opacity: op}}>
                <div style={{height: 260, display: "flex", alignItems: "center"}}>
                  <Dots r={c.r} cols={c.cols} rows={c.rows} color={c.mid && hl > 0.5 ? C.accent : C.mute} />
                </div>
                <div style={{textAlign: "center"}}>
                  <div style={{fontSize: 58, fontWeight: 700, color: C.ink}}>{c.label}</div>
                  <div style={{fontSize: 46, color: c.mid && hl > 0.5 ? C.accent : C.mute, marginTop: 6}}>{c.note}</div>
                </div>
              </div>
            </Reveal>
          );
        })}
      </div>
    </Stage>
  );
}

