import React from "react";
import {AbsoluteFill, interpolate, spring, useCurrentFrame, useVideoConfig} from "remotion";

export const C = {bg: "#0e0c0a", ink: "#f5efe6", mute: "#a39a8e", dim: "#3a342d", accent: "#f2a33a"};
export const FONT = "Segoe UI, system-ui, sans-serif";

export const useEnter = (delay: number) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  return spring({frame: frame - delay, fps, config: {damping: 200}});
};

export const Reveal: React.FC<{delay: number; children: React.ReactNode; style?: React.CSSProperties}> = ({delay, children, style}) => {
  const e = useEnter(delay);
  return <div style={{opacity: e, transform: `translateY(${interpolate(e, [0, 1], [36, 0])}px)`, ...style}}>{children}</div>;
};

export const Stage: React.FC<{index: string; kicker: string; title: string; children: React.ReactNode}> = ({index, kicker, title, children}) => {
  const frame = useCurrentFrame();
  const {durationInFrames} = useVideoConfig();
  const out = interpolate(frame, [durationInFrames - 12, durationInFrames], [1, 0], {extrapolateLeft: "clamp", extrapolateRight: "clamp"});
  return (
    <AbsoluteFill style={{background: C.bg, color: C.ink, fontFamily: FONT, padding: "110px 120px", opacity: out}}>
      <Reveal delay={0}>
        <div style={{fontSize: 34, letterSpacing: 6, textTransform: "uppercase", color: C.accent, fontWeight: 600}}>{index} · {kicker}</div>
      </Reveal>
      <Reveal delay={6}>
        <h1 style={{fontSize: 120, margin: "18px 0 0", fontWeight: 700, lineHeight: 1.05}}>{title}</h1>
      </Reveal>
      <div style={{flex: 1, marginTop: 50, position: "relative"}}>{children}</div>
    </AbsoluteFill>
  );
};

